{
  "name": "prompt-engineer",
  "version": "1.0.0",
  "description": "A registry for machine-authored prompts that scores every one against a 6-dimension quality rubric, refuses the ones below the floor, flags comfort-zone and grandiosity anti-patterns, versions them, and tracks parent→child lineage — so a system that writes its own prompts gets measurably better at it.",
  "license": "MIT",
  "type": "commonjs",
  "scripts": {
    "test": "node examples/demo.cjs >/dev/null && echo ok",
    "check": "node --check lib/prompt-engineer.cjs && node --check examples/demo.cjs && echo ok"
  },
  "keywords": [
    "prompt-engineering",
    "prompt-evolution",
    "quality-rubric",
    "self-improvement",
    "prompt-genealogy",
    "autonomous-agents",
    "zero-dependencies"
  ],
  "engines": {
    "node": ">=18"
  },
  "dependencies": {},
  "devDependencies": {},
  "bin": {
    "prompt-engineer": "lib/prompt-engineer.cjs"
  }
}
